import {mountShell} from './shell.js?v=quiet-2&online-alerts=1';
import {Cloud} from './cloud.js?v=outage-1';
import {leaderboardRow,latestLeaderboard} from './leaderboard-model.js?v=avatar-1';
import {createViewCache} from './view-cache.js?v=avatar-1';
import {hydrateLeaderboardAvatars,releaseAvatarObjectUrls} from './avatar-cache.js?v=avatar-1';
const $=id=>document.getElementById(id),shell=mountShell();let page=0,scope=location.hash==='#friends'?'friends':'global',accountGeneration=0,lastOwner=null;
const cloud=new Cloud(()=>accountChanged());shell.connect(cloud);
const cache=createViewCache();
const loader=latestLeaderboard(async(action,query,owner)=>{
 const {force=false,...filters}=query;
 if(!force){const saved=cache.board(owner,filters,{allowStale:true});if(saved)return {...saved,_cached:true};}
 const fresh=await cloud.request(action,filters,owner);
 if(cloud.user?.id===owner)cache.saveBoard(owner,filters,fresh);
 return {...fresh,_cached:false};
});
function setMessage(text,error=false){$('leaderMessage').textContent=text;$('leaderMessage').classList.toggle('error',error);$('leaderAuthMessage').textContent=text;$('leaderAuthMessage').classList.toggle('error',error);}
function selectScope(){for(const button of document.querySelectorAll('[data-board]')){const active=button.dataset.board===scope;button.setAttribute('aria-selected',String(active));button.tabIndex=active?0:-1;}const selected=document.querySelector('[data-board="'+scope+'"]');$('leaderPanel').setAttribute('aria-labelledby',selected.id);$('boardHeading').textContent=scope==='friends'?'Friends leaderboard':'Global leaderboard';$('boardDescription').textContent=scope==='friends'?'You and the people you follow, in one place.':'A shared place for every discoverable learner.';}
function clearResults(){releaseAvatarObjectUrls();for(const id of ['yourRank','yourPoints','yourSolved','rankedLearners'])$(id).textContent='—';$('leaderRows').replaceChildren();$('leaderFindMe').hidden=true;$('leaderEmpty').hidden=true;$('leaderError').hidden=true;$('leaderPager').hidden=true;$('yourPosition').hidden=true;$('profileNudge').hidden=true;}
async function load({force=false}={}){
 const owner=cloud.user?.id;if(!owner)return;selectScope();clearResults();$('leaderPanel').setAttribute('aria-busy','true');$('leaderLoading').hidden=false;$('leaderRefresh').disabled=true;setMessage('Loading rankings…');
 try{const response=await loader.load({scope,period:$('leaderPeriod').value,page,force},owner);if(!response)return;
  const r=response.result;if(page>0&&!r.users.length){page=Math.max(0,Math.ceil(r.total/r.pageSize)-1);load();return;}
  $('leaderRows').innerHTML=r.users.map(leaderboardRow).join('');$('leaderRows').querySelectorAll('img').forEach(img=>img.onerror=()=>img.remove());$('leaderFindMe').hidden=!$('leaderRows').querySelector('.your-ranking');
  void hydrateLeaderboardAvatars($('leaderRows'),owner); // Rehydrate saved image bytes, even after signed URLs expire.
  $('yourRank').textContent=r.me?'#'+r.me.rank:'—';$('yourPoints').textContent=r.me?.points??'—';$('yourSolved').textContent=r.me?.solved??'—';$('rankedLearners').textContent=r.total;
  $('leaderEmpty').hidden=!!r.users.length;$('emptyTitle').textContent=scope==='friends'?'Build your practice circle.':'Be the first on the board.';$('emptyDescription').textContent=scope==='friends'?'Create a discoverable profile, then find and follow friends using the search above.':'Create a discoverable profile to join the leaderboard.';
  $('profileNudge').hidden=!!r.discoverable;$('profileNudgeText').textContent=r.hasProfile?'Make your profile discoverable to appear in the rankings.':'Create a profile to join the rankings and compare with friends.';
  $('friendHint').hidden=scope!=='friends'||r.total>1;
  const start=page*r.pageSize+1,end=Math.min((page+1)*r.pageSize,r.total);$('pageRange').textContent=r.total?start+'–'+end+' of '+r.total+' learners':'0 learners';$('leaderPager').hidden=r.total<=r.pageSize;$('leaderPrevious').disabled=page===0;$('leaderNext').disabled=end>=r.total;
  $('yourPosition').hidden=!r.me||r.users.some(p=>p.isYou);$('yourPosition').textContent=r.me?'Your position: #'+r.me.rank+' · '+r.me.points+' points · '+r.me.solved+' solved in this period.':'';
  setMessage(r._cached?'Saved rankings · Press Refresh ranks for the latest positions.':'Rankings updated from the server.');$('leaderLoading').hidden=true;$('leaderPanel').setAttribute('aria-busy','false');$('leaderRefresh').disabled=false;
 }catch(e){if(cloud.user?.id!==owner)return;$('leaderLoading').hidden=true;$('leaderError').hidden=false;$('leaderErrorText').textContent=e.message;$('leaderPanel').setAttribute('aria-busy','false');$('leaderRefresh').disabled=false;setMessage('Rankings could not be loaded.',true);}
}
async function accountChanged(){
 const ticket=++accountGeneration;loader.cancel();const nextOwner=cloud.user?.id||null;if(lastOwner&&lastOwner!==nextOwner)cache.clearOwner(lastOwner);lastOwner=nextOwner;shell.setAccount(cloud.user);shell.setAdmin(false);clearResults();const signedIn=!!cloud.user;
 $('leaderAuthMessage').hidden=signedIn;$('leaderSignedOut').hidden=signedIn;$('leaderSignedIn').hidden=!signedIn;$('communityAccount').textContent=signedIn?'Sign out':'Sign in with Google';
 if(!signedIn){setMessage('Sign in to see the community and your friends.');return;}
 // Show cached rankings immediately; load verified profile details independently.
 // Neither the account response nor notifications are cached.
 const rankings=load();
 const savedAccount=cache.self(nextOwner);
 // Cache only presentation data. Administrator navigation always starts hidden
 // until the current authenticated role has been checked against the backend.
 if(savedAccount)shell.setAccount(cloud.user,savedAccount.profile);
 try{
   const own=await cloud.request('self');
   if(ticket===accountGeneration&&cloud.user?.id===nextOwner){
     cache.saveSelf(nextOwner,own);
     shell.setAccount(cloud.user,own.profile);
     shell.setAdmin(own.admin===true);
   }
 }catch(e){
   if(ticket===accountGeneration)console.warn('ByteQuest administrator role could not be refreshed:',e.message);
 }
 await rankings;
}
async function login(){try{await cloud.signIn();}catch(e){setMessage(e.message,true);}}
$('leaderSignIn').onclick=login;$('communityAccount').onclick=async()=>{try{if(cloud.user)await cloud.signOut();else await login();}catch(e){setMessage(e.message,true);}};
document.querySelectorAll('[data-board]').forEach(button=>{button.onclick=()=>{const next=button.dataset.board;if(next===scope)return;location.hash=next;};button.onkeydown=e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const next=e.key==='Home'?'global':e.key==='End'?'friends':scope==='global'?'friends':'global';document.querySelector('[data-board="'+next+'"]').focus();if(next!==scope)location.hash=next;};});
addEventListener('hashchange',()=>{scope=location.hash==='#friends'?'friends':'global';page=0;selectScope();load();});$('leaderPeriod').onchange=()=>{page=0;load();};$('leaderRefresh').onclick=()=>load({force:true});$('leaderFindMe').onclick=()=>{const row=$('leaderRows').querySelector('.your-ranking');if(!row)return;row.tabIndex=-1;row.scrollIntoView({block:'center',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});row.focus({preventScroll:true});};$('leaderRetry').onclick=()=>accountChanged();$('leaderPrevious').onclick=()=>{if(page>0){page--;load();}};$('leaderNext').onclick=()=>{page++;load();};
addEventListener('pagehide',releaseAvatarObjectUrls);
selectScope();cloud.init().then(accountChanged).catch(e=>{setMessage(e.message,true);$('leaderSignedOut').hidden=false;});

// A durable cursor recovers transitions that snapshot polling can miss. Tokens stay in headers.
export function mountLiveEvents(cloud,{onBatch=()=>{},onResume=()=>{},win=window,doc=document}={}){
 let owner=null,cursor=null,announcementCursor=null,generation=0,controller=null,retry=null,disposed=false,failures=0;
 const visible=()=>doc.visibilityState==='visible'&&doc.hasFocus()&&!cloud.deletionPending;
 const key=id=>'bytequest.live.'+id;const updateKey=id=>'bytequest.announcements.'+id;
 function stop(){generation++;controller?.abort();controller=null;win.clearTimeout(retry);retry=null;}
 function remember(value){if(!Number.isSafeInteger(value)||value<0)return;cursor=value;try{win.sessionStorage.setItem(key(owner),String(value));}catch{}}
 function consume(batch,ticket,user){if(ticket!==generation||user!==owner||!visible())return;const previous=cursor,previousUpdate=announcementCursor;remember(batch.cursor);if(Number.isSafeInteger(batch.announcementCursor)&&batch.announcementCursor>=0){announcementCursor=batch.announcementCursor;try{win.sessionStorage.setItem(updateKey(owner),String(announcementCursor));}catch{}}onBatch({...batch,announcements:(batch.announcements||[]).filter(e=>previousUpdate!==null&&e.id>previousUpdate),events:(batch.events||[]).filter(e=>previous===null||e.id>previous)});}
 async function connect(){
  if(disposed||!owner||!visible()||controller)return;const ticket=generation,user=owner;controller=new AbortController();const signal=controller.signal;
  try{
   if(failures>=2){const batch=await cloud.request('live-events-poll',{after:cursor,announcementsAfter:announcementCursor},user);consume(batch,ticket,user);}
   else await cloud.openLive({after:cursor,announcementsAfter:announcementCursor,signal,onBatch:batch=>consume(batch,ticket,user)},user);
   if(ticket!==generation)return;failures=failures>=2?failures+1:0;if(failures>=8)failures=0;
  }catch(e){if(ticket!==generation||signal.aborted)return;failures++;}
  finally{if(ticket===generation){controller=null;if(visible()&&owner)retry=win.setTimeout(connect,failures>=2?2000:failures?1500:300);}}
 }
 function visibility(){if(visible()){onResume();connect();}else stop();}
 win.addEventListener('focus',visibility);win.addEventListener('blur',visibility);win.addEventListener('online',visibility);doc.addEventListener('visibilitychange',visibility);win.addEventListener('pagehide',stop);
 return{setOwner(user){const next=user?.id||null;if(next===owner){if(cloud.deletionPending)stop();return;}stop();owner=next;cursor=null;announcementCursor=null;failures=0;try{const saved=win.sessionStorage.getItem(key(next));if(next&&saved!==null&&Number.isSafeInteger(Number(saved))&&Number(saved)>=0)cursor=Number(saved);const updates=win.sessionStorage.getItem(updateKey(next));if(next&&updates!==null&&Number.isSafeInteger(Number(updates))&&Number(updates)>=0)announcementCursor=Number(updates);}catch{}if(owner)connect();},dispose(){disposed=true;stop();owner=null;win.removeEventListener('focus',visibility);win.removeEventListener('blur',visibility);win.removeEventListener('online',visibility);doc.removeEventListener('visibilitychange',visibility);win.removeEventListener('pagehide',stop);}};
}

:root{color-scheme:dark;--bg:#080c0b;--panel:#101614;--line:#263b31;--ink:#e9f3eb;--muted:#a3b2a8;--accent:#78e3a8}
*{box-sizing:border-box}html,body{min-height:100%;margin:0}
body{font:14px/1.6 Inter,system-ui,sans-serif;color:var(--ink);background:radial-gradient(circle at 78% 8%,#12412b55,transparent 38%),var(--bg)}
button,input,select,textarea{font:inherit}a{color:inherit;text-decoration:none}
button{cursor:pointer}button:disabled{opacity:.45;cursor:not-allowed}
a:focus-visible,button:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible{outline:2px solid var(--accent);outline-offset:3px}
[hidden]{display:none!important}
.ma-header{display:flex;justify-content:space-between;gap:20px;align-items:center;padding:26px max(24px,calc((100vw - 1120px)/2));border-bottom:1px solid var(--line)}
.ma-logo{font-size:21px;letter-spacing:-.8px;font-weight:600}.ma-logo strong{font-weight:650;color:var(--accent)}
.ma-header-actions{display:flex;gap:24px;align-items:center;flex-wrap:wrap;font-size:12px;color:var(--muted)}
.ma-header-actions>span,.ma-eyebrow,.ma-overview-meta>span,.ma-hint{font:11px/1.3 'JetBrains Mono',monospace;letter-spacing:.09em}
.ma-header-actions a:hover,.ma-guide a:hover{color:var(--accent)}
.ma-shell{max-width:1120px;margin:0 auto;padding:66px 24px 80px}
.ma-eyebrow{color:var(--accent);margin:0 0 16px}
.ma-shell>h1{font-size:clamp(41px,6vw,73px);line-height:1.1;letter-spacing:-.065em;margin:0 0 16px}
.ma-shell>h1 span{color:var(--accent)}.ma-description{color:var(--muted);font-size:16px;max-width:670px;margin:0 0 38px}
.ma-panel,.ma-overview,.ma-guide{background:#101713df;border:1px solid var(--line);border-radius:19px;padding:clamp(22px,4vw,38px)}
.ma-panel h2,.ma-overview h2,.ma-guide h2{font-size:20px;letter-spacing:-.03em;line-height:1.3;margin:0 0 11px}
.ma-panel p,.ma-overview p,.ma-guide p{color:var(--muted)}
.ma-overview{display:flex;justify-content:space-between;gap:30px;margin-bottom:20px;align-items:center}
.ma-tag{display:inline-block;color:var(--accent);font:10px 'JetBrains Mono',monospace;letter-spacing:.14em;padding:6px 11px;border-radius:7px;border:1px solid #407154;background:#78e3a812;margin-bottom:13px}
.ma-overview-meta{display:flex;flex-direction:column;align-items:flex-end;gap:7px;color:var(--muted);min-width:180px}
.ma-overview-meta strong{color:var(--ink);font-size:13px}
.ma-overview-meta button{border:0;background:none;color:var(--accent);font-size:12px;padding:4px 0}
.ma-section-head{display:flex;align-items:flex-start;justify-content:space-between;gap:20px;margin-bottom:30px}
.ma-section-head .ma-eyebrow{margin-bottom:10px}.ma-hint{color:var(--muted);font-size:10px;max-width:215px;text-align:right}
.ma-form-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}
.ma-field{display:flex;flex-direction:column;gap:9px;min-width:0}
.ma-field>span{font-size:12px;font-weight:600;color:#d7e6d9}
.ma-field input,.ma-field select,.ma-field textarea{width:100%;min-height:45px;border-radius:9px;border:1px solid #3b5044;background:#0b100f;color:#f4faf5;padding:10px 12px}
.ma-field textarea{resize:vertical}.ma-field small{color:var(--muted);align-self:flex-end}
.ma-message{margin-top:25px}.ma-notice{margin:28px 0;padding:15px 18px;background:#12302466;border-left:2px solid var(--accent);border-radius:8px;color:#b9d4c2;font-size:12px;line-height:1.8}
.ma-notice strong{color:var(--ink)}.ma-buttons{display:flex;gap:10px;flex-wrap:wrap}
.ma-buttons button,.ma-panel button{padding:11px 18px;border-radius:10px;border:1px solid var(--line);font-size:12px;font-weight:600;min-height:43px}
.ma-outline{background:#18251e;color:var(--ink)}.ma-primary{background:var(--accent);color:#082010!important;border-color:var(--accent)!important}
.ma-danger{background:#2f1515;color:#ffa1a1;border-color:#824545!important}
.ma-guide{margin-top:20px;display:flex;align-items:center;justify-content:space-between;gap:20px}
.ma-guide p{max-width:680px;margin-bottom:0}.ma-guide a{white-space:nowrap;font-size:12px;color:var(--accent)}
.ma-feedback{min-height:22px;margin:22px 0 0;color:var(--accent)}
.ma-feedback[data-error="true"]{color:#ffa1a1}
#maSignIn,#maRetry{background:var(--accent);border:0!important;color:#08140e;padding:12px 22px;border-radius:10px;font-weight:600}
@media(max-width:850px){.ma-form-grid{grid-template-columns:1fr 1fr}.ma-field:first-child{grid-column:1/-1}.ma-section-head{flex-wrap:wrap}.ma-hint{text-align:left}}
@media(max-width:600px){.ma-shell{padding:43px 20px 65px}.ma-header{padding:20px}.ma-header-actions{gap:9px}.ma-header-actions>span{display:none}.ma-form-grid{grid-template-columns:1fr}.ma-field:first-child{grid-column:auto}.ma-overview,.ma-guide{flex-direction:column;align-items:stretch}.ma-overview-meta{align-items:flex-start}.ma-buttons button{width:100%}}
@media(prefers-reduced-motion:reduce){*,*:before,*:after{animation:none!important;transition:none!important}}

import {Cloud} from './cloud.js?v=outage-1';
import {isoToISTInput,istInputToISO,istDisplay} from './maintenance-model.js?v=1';

const $=id=>document.getElementById(id);
const cloud=new Cloud(()=>{void checkAccess();});
let current=null,epoch=0,busy=false;
function message(text,isError=false){$('maFeedback').textContent=text;$('maFeedback').dataset.error=String(isError);}
function showAuth(text,{login=false,retry=false}={}){
 $('maAuth').hidden=false;$('maControl').hidden=true;
 $('maAuthText').textContent=text;
 $('maSignIn').hidden=!login;
 $('maRetry').hidden=!retry;

