// Never overwrite an unreadable progress record. Use a separate recovery slot
// so a malformed JSON value or an incompatible backup remains recoverable.
export function readSafeProgress(storage,key,validate,blank){
  const recoveryKey=key+'.recovery';
  try{
    const recovery=storage.getItem(recoveryKey);
    if(recovery!==null){
      try{return {state:validate(JSON.parse(recovery)),saveKey:recoveryKey,warning:'The original damaged progress record is preserved.'};}
      catch{return {state:blank(),saveKey:null,warning:'The recovery record is unreadable. Neither copy will be overwritten.'};}
    }
    const raw=storage.getItem(key);
    if(raw===null)return {state:blank(),saveKey:key,warning:null};
    try{return {state:validate(JSON.parse(raw)),saveKey:key,warning:null};}
    catch{
      return {state:blank(),saveKey:recoveryKey,warning:'An unreadable original progress record was preserved. New work will use a separate recovery copy.'};
    }
  }catch{
    return {state:blank(),saveKey:null,warning:'Browser storage could not be read. Export your work before closing this page.'};
  }
}
export function writeSafeProgress(storage,saveKey,state){
  if(!saveKey)throw new Error('Storage is unavailable or the recovery record needs attention.');
  storage.setItem(saveKey,JSON.stringify(state));
}

// Pure request coalescing: duplicate read calls made while an identical
// request is still in flight share its result. No private responses are cached.
// Presence, chat, notifications, auth, progress and any write are excluded.
export const COALESCED_READS=new Set([
 'self','profile','leaderboard','search','followers','following','friend-analytics',
 'submission-list','submission-history','submission-read','problem-authors'
]);
export function createRequestCoordinator({clock=()=>globalThis.performance?.now?.()??Date.now()}={}){
 const pending=new Map(),samples=new Map();
 let avoided=0;
 const keyFor=(owner,action,body)=>{
  if(!owner||!COALESCED_READS.has(action)||!body||typeof body!=='object'||Array.isArray(body))return null;
  let pairs;
  try{pairs=Object.entries(body).sort(([a],[b])=>a.localeCompare(b));
   if(pairs.some(([,v])=>v&&typeof v==='object'&&!Array.isArray(v)||Array.isArray(v)&&v.some(x=>typeof x==='object')))return null;
   return JSON.stringify([owner,action,pairs]);
  }catch{return null;}
 };
 const record=(action,elapsed,success)=>{
  if(!Number.isFinite(elapsed)||elapsed<0)return;
  const values=samples.get(action)||[];
  values.push(Math.round(elapsed));
  if(values.length>50)values.shift();
  samples.set(action,values);
 };
 function run(action,body,owner,task){
  const key=keyFor(owner,action,body);
  if(key&&pending.has(key)){avoided++;return pending.get(key);}
  const start=clock();
  const work=Promise.resolve().then(task);
  const monitored=work.then(result=>{record(action,clock()-start,true);return result;},error=>{record(action,clock()-start,false);throw error;});
  if(!key)return monitored;
  // Clear on settle (success or failure). A later manual Refresh always
  // hits the network, and a follower/profile update is never hidden by TTL.
  const shared=monitored.finally(()=>{if(pending.get(key)===shared)pending.delete(key);});
  pending.set(key,shared);
  return shared;
 }
 function metrics(){
  const out={avoided,active:pending.size,actions:{}};
  for(const [action,items] of samples){
   const sorted=[...items].sort((a,b)=>a-b);
   out.actions[action]={count:items.length,p50:sorted[Math.floor((sorted.length-1)*.5)],
    p95:sorted[Math.floor((sorted.length-1)*.95)]};
  }
  return out;
 }
 return {run,metrics,clear(){pending.clear();samples.clear();avoided=0;}};
}

import {escapeHtml as h} from './community-model.js';
export const pointValues=Object.freeze({Easy:10,Medium:25,Hard:50});
export const pointsFor=difficulty=>pointValues[difficulty]||0;
export function totalPoints(progress,catalog,now=Date.now()){return catalog.reduce((sum,p)=>{const at=progress.solved?.[p.id];return sum+(Number.isFinite(at)&&at>0&&at<=now?pointsFor(p.difficulty):0);},0);}
export function rankCup(rank){const name=({1:'Gold',2:'Silver',3:'Bronze'})[rank];if(!name)return '';return '<svg class="rank-cup '+name.toLowerCase()+'" viewBox="0 0 32 32" role="img" aria-label="'+name+' cup, rank '+h(rank)+'"><title>'+name+' · Rank '+h(rank)+'</title><path fill="currentColor" d="M9 4h14v9a7 7 0 0 1-6 6.93V24h5v4H10v-4h5v-4.07A7 7 0 0 1 9 13V4Z"/><path d="M9 7H5v4a6 6 0 0 0 6 6m12-10h4v4a6 6 0 0 1-6 6" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linejoin="round"/><path d="M12 6v6" stroke="white" stroke-opacity=".45" stroke-width="1.5" stroke-linecap="round"/></svg>';}

const ribbonPalette=Object.freeze({
  gold:{rim:'#f2ae16',edge:'#ffda55',face:'#ffd22e',inner:'#ffe679',star:'#e99b00'},
  silver:{rim:'#8795a5',edge:'#c9d5df',face:'#aebfce',inner:'#dce5ed',star:'#7c8fa4'},
  bronze:{rim:'#9c451f',edge:'#d88d4d',face:'#bf6536',inner:'#e6a565',star:'#87401e'}
});
function shapePoints(cx,cy,outer,inner,count=32,shift=-Math.PI/2){
 return Array.from({length:count},(_,i)=>{
  const angle=shift+i*Math.PI*2/count,rad=i%2?inner:outer;
  return (cx+Math.cos(angle)*rad).toFixed(1)+','+(cy+Math.sin(angle)*rad).toFixed(1);
 }).join(' ');
}
const ribbonSeal=shapePoints(34,29,27,24.8);
const ribbonStar=shapePoints(34,29,15.2,7.1,10);
