const channel = "bytequest-java";
const send = data => parent.postMessage({channel,...data}, location.origin);
let Runner;
let running = false;
try {
  if (typeof cheerpjInit !== "function") throw new Error("The Java runtime CDN is unavailable. Check your connection and try again.");
  send({type:"status",message:"Loading the browser JDK. The first launch can take a minute."});
  await cheerpjInit({version:17,status:"none",javaProperties:["java.io.tmpdir=/files"]});
  const jar = "/app" + new URL("java-runner.jar", location.href).pathname;
  const lib = await cheerpjRunLibrary(jar);
  Runner = await lib.quest.JavaRunner;
  // Warm javac too: loading the JVM alone leaves the compiler's first-use download on Run.
  send({type:"status",message:"Preparing the Java compiler in the background…"});
  const warm=JSON.parse(await Runner.run("class Solution { public int warmup() { return 0; } }",'check("Compiler warm-up", () -> new Solution().warmup(), 0);'));
  if(warm.status!=="ok"||!warm.cases.every(c=>c.passed))throw new Error("Compiler warm-up failed.");
  send({id:"boot",type:"ready",result:true});
} catch (error) {
  send({id:"boot",type:"error",message:"Java could not start: " + String(error.message || error)});
}
addEventListener("message", async event => {
  if (event.source !== parent || event.origin !== location.origin || event.data?.channel !== channel || event.data.type !== "run") return;
  const {id,source,tests} = event.data;
  if (!Runner || running) { send({id,type:"error",message:"The Java runtime is busy or not ready."}); return; }
  running = true;
  try { send({id,type:"result",result:JSON.parse(await Runner.run(source,tests))}); }
  catch (error) { send({id,type:"error",message:String(error.message || error)}); }
  finally { running = false; }
});

// Keep ByteQuest's native Java-runner isolation headers intact, and cache
// ONLY the standalone connection recovery page. Never cache account progress,
// private judge responses, source code, or authenticated API traffic.
const RECOVERY_CACHE='bytequest-connection-page-v4';
const RECOVERY_ASSETS=[
 './status.html','./system-state.css?v=maintenance-controls-1','./status-page.js?v=strict-1',
 './system-state.js?v=1','./theme-mode.js'
];
const recoverable=new Set(['status.html','system-state.css','status-page.js','system-state.js','theme-mode.js']);
self.addEventListener('install',event=>{
  event.waitUntil(caches.open(RECOVERY_CACHE).then(cache=>
    Promise.allSettled(RECOVERY_ASSETS.map(url=>cache.add(url)))
  ).catch(()=>{})); // Disabled Cache Storage must not block app installation.
  self.skipWaiting();
});
self.addEventListener('activate',event=>event.waitUntil(self.clients.claim()));
self.addEventListener('fetch',event=>{
  const url=new URL(event.request.url);
  if(url.origin!==self.location.origin||event.request.method!=='GET')return;
  if(url.pathname.endsWith('/native-runner.html')){
    // Original COOP/COEP behavior, required for the browser Java runner.
    event.respondWith((async()=>{
      const response=await fetch(event.request);
      const headers=new Headers(response.headers);
      headers.set('Cross-Origin-Opener-Policy','same-origin');
      headers.set('Cross-Origin-Embedder-Policy','require-corp');
      headers.set('Cache-Control','no-store');
      return new Response(response.body,{status:response.status,statusText:response.statusText,headers});
    })());
    return;
  }
  const file=url.pathname.slice(url.pathname.lastIndexOf('/')+1);
  if(!recoverable.has(file))return;
  event.respondWith((async()=>{
    let cache=null;
    try{cache=await caches.open(RECOVERY_CACHE);}catch{}
    try{
      const response=await fetch(event.request);
      if(response.ok&&cache)await cache.put(event.request,response.clone()).catch(()=>{});
      return response;
    }catch{
      const saved=cache?await cache.match(event.request,{ignoreSearch:true}).catch(()=>null):null;
      return saved||Response.error();
    }
  })());
});

/* Scroll paint optimizations.
 * Keep the ByteQuest visual theme while avoiding continuous viewport repaints.
 * Do not affect authentication, data caches, rankings, chat or notifications.
 */

/* This decorative grid/gradient used to be a full-screen fixed layer with a
 * perpetual opacity animation. Make it a static top-of-page ornament instead,
 * so it scrolls with the document rather than being recomposited each frame.
 */
body::before{
  position:absolute!important;
  inset:0 0 auto 0!important;
  height:min(780px,100vh)!important;
  animation:none!important;
}

/* A sticky, 20–28px backdrop blur forces the browser to continuously sample
 * scrolling page content underneath the navbar. Use an opaque surface instead.
 * The existing shape, border, text, theme and subtle shadow remain unchanged.
 */
.minimal-header{
  background:var(--surface)!important;
  -webkit-backdrop-filter:none!important;
  backdrop-filter:none!important;
}

/* Keep chart/summary content in the DOM but skip painting distant static
 * profile sections until they approach the viewport.
 * Avoid tables, sticky headers, editors, menus and interactive graphs, whose
 * layout/measurement behavior must remain unchanged.
 */
@supports(content-visibility:auto){
  .profile-expertise,
  .month-calendar-scroll{
    content-visibility:auto;
    contain-intrinsic-size:auto 155px;
  }
  .profile-expertise{contain-intrinsic-size:auto 235px}
}

/* Decorative gradients do not need to repaint on cursor movement over
 * full-width scroll surfaces. Logo hover tooltips and +N company tags remain.
 */
#questGrid.bq-spotlight,
.leader-table-wrap.bq-spotlight{
  background-image:none!important;
}

@media(prefers-reduced-motion:reduce){
  .minimal-header{transition:none!important}
}

