.status-top-rule{height:14px;width:1px;background:var(--line)}
.status-main{display:grid;place-items:center;flex:1;width:100%;padding:46px clamp(24px,6.2vw,112px)}
.status-shell{width:min(1260px,100%);display:grid;grid-template-columns:minmax(0,1fr) minmax(350px,1fr);align-items:center;gap:clamp(48px,7vw,118px)}
