.status-copy h1 em{font:italic 1.08em/1 "Instrument Serif",Georgia,serif;color:var(--accent);letter-spacing:-.035em}
.status-lead{font-size:clamp(16px,1.35vw,19px);line-height:1.7;color:#b8c5be;max-width:480px;margin:0}
.status-divider{height:1px;background:linear-gradient(to right,var(--line),transparent);margin:42px 0 28px}
.status-safety{display:flex;align-items:flex-start;gap:16px}
