.status-action-secondary{border:1px solid rgba(214,238,223,.19);color:#e1eee5;background:rgba(255,255,255,.035)}
.status-action-secondary:hover{border-color:var(--accent-line);transform:translateY(-2px)}
.status-feedback{font-size:12px;color:var(--accent);min-height:20px;margin:18px 0 0}
.status-illustration{position:relative;isolation:isolate;min-width:0;max-width:620px}
.status-visual-frame{position:relative;border:1px solid var(--line);border-radius:27px;background:radial-gradient(circle at 50% 42%,var(--accent-dim),transparent 60%),linear-gradient(146deg,rgba(255,255,255,.033),rgba(255,255,255,.008));overflow:hidden;box-shadow:0 26px 90px -45px rgba(0,0,0,.85),inset 0 1px rgba(255,255,255,.055);aspect-ratio:1/.95}
.status-visual-frame:before{content:"";pointer-events:none;position:absolute;inset:0;background:linear-gradient(to right,rgba(180,220,191,.05) 1px,transparent 1px),linear-gradient(to bottom,rgba(180,220,191,.05) 1px,transparent 1px);background-size:45px 45px;mask-image:radial-gradient(circle at center,#0008,transparent 75%)}
.visual-overline,.visual-footnote{position:absolute;left:28px;right:28px;color:#8c9a93}
.visual-overline{top:28px}
.visual-footnote{bottom:24px;display:flex;justify-content:space-between;border-top:1px solid var(--line);padding-top:15px}
.visual-footnote span:last-child{color:var(--accent)}
.status-network{position:absolute;inset:7% 0 3%;width:100%;height:85%;color:var(--accent)}
.ring{opacity:.16;stroke-dasharray:4 9}.ring-outer{animation:rotate 45s linear infinite;transform-origin:240px 222px}.ring-inner{opacity:.3;animation:rotate 38s linear infinite reverse;transform-origin:240px 222px}.ring-core{opacity:.22;stroke-dasharray:2 10}
.core-glow{fill:var(--accent-dim)}.network-edge{opacity:.67}.network-broken{opacity:.85;animation:dash 2.9s linear infinite}
.network-ticks{opacity:.22}.network-node{fill:#15211d;stroke:var(--accent);stroke-width:2}.network-alert{fill:var(--accent);filter:drop-shadow(0 0 10px var(--accent))}.network-alert-mark{stroke:var(--accent);opacity:.7}
.core-halo{opacity:.45;fill:var(--accent-dim)}.core-dot{fill:var(--accent);filter:drop-shadow(0 0 18px var(--accent))}.core-symbol{stroke:#0a1511}
.visual-corner{position:absolute;width:18px;height:18px;border-color:var(--accent);opacity:.7}.visual-corner-a{top:-8px;left:-8px;border-left:1px solid;border-top:1px solid}.visual-corner-b{bottom:-8px;right:-8px;border-right:1px solid;border-bottom:1px solid}
.status-footer{padding:24px clamp(24px,6.2vw,112px);border-top:1px solid var(--line);display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:18px;color:#81938a;font-size:10px}
.status-footer>span{display:flex;align-items:center;gap:9px}.status-footer-dot{width:5px;height:5px;border-radius:50%;background:var(--accent)}
.status-provider-links{display:flex;gap:24px}.status-provider-links a:hover{color:var(--accent)}
@keyframes rotate{to{transform:rotate(360deg)}}@keyframes pulse{50%{box-shadow:0 0 0 10px transparent}}@keyframes dash{to{stroke-dashoffset:-40}}
@media(max-width:900px){.status-shell{grid-template-columns:1fr;gap:40px;max-width:690px}.status-copy{max-width:100%}.status-illustration{max-width:560px;width:100%;margin-inline:auto}.status-main{padding:58px 28px}.status-copy h1{font-size:clamp(52px,9vw,80px)}}
@media(max-width:600px){.status-top{padding:24px}.status-top-meta{font-size:9px;gap:8px}.status-main{padding:48px 24px}.status-shell{gap:34px}.status-copy h1{font-size:clamp(44px,11vw,60px)}.status-lead{font-size:15px}.status-divider{margin:30px 0 23px}.status-actions{margin-top:30px}.status-action-primary,.status-action-secondary{width:100%}.status-visual-frame{border-radius:20px;aspect-ratio:1/.77}.visual-overline{top:16px;left:18px;font-size:9px}.visual-footnote{bottom:14px;left:18px;right:18px;font-size:9px}.status-footer{padding:24px;gap:12px}.status-provider-links{gap:18px}.status-network{height:97%;inset:1% 0 2%}}
@media(prefers-reduced-motion:reduce){*,*:before,*:after{animation:none!important;transition:none!important;scroll-behavior:auto!important}}
@media(forced-colors:active){.status-action-primary{color:ButtonText;background:ButtonFace}.status-network{color:CanvasText}}


/* Keep recovery actions on offline/busy/unreachable pages, never maintenance.
   An early head marker prevents a flash of the buttons before modules load. */
html[data-maintenance-page="true"] .status-actions,
body[data-issue="maintenance"] .status-actions{display:none!important}
.status-actions>[hidden]{display:none!important}
/* Server-authenticated maintenance window; never populated from URL params. */
.status-window[hidden],.status-admin-link[hidden]{display:none!important}
.status-window{display:flex;flex-direction:column;align-items:flex-start;gap:7px;margin-top:27px;padding:17px 20px;border:1px solid var(--accent-line);background:var(--accent-dim);border-radius:13px}
.status-window>span:first-child{font:10px/1.5 "JetBrains Mono",monospace;letter-spacing:.1em;color:var(--accent)}
.status-window strong{font-size:20px;line-height:1.4;letter-spacing:-.02em}
.status-window>span:last-child{font-size:12px;color:var(--muted)}
.status-admin-link{display:inline-block;margin-top:12px;font-size:12px;color:var(--accent);text-decoration:underline;text-underline-offset:4px}

// Deterministic outage classifications shared by network alerts and the
// standalone ByteQuest recovery page. No outage is inferred from HTTP 401/403
// or a single failed submission-verification request.
const issues=new Set(['offline','busy','unreachable','maintenance']);
const pages=new Set(['index.html','leaderboard.html','community.html','studio.html']);
const maintenanceCodes=new Set(['MAINTENANCE','MAINTENANCE_MODE','PLANNED_MAINTENANCE']);
export function safeReturnPage(input){
  if(typeof input!=='string')return 'index.html';
  const value=input.startsWith('./')?input.slice(2):input;
  return pages.has(value)?value:'index.html';
}
export function connectionPageUrl(issue,returnPage='index.html'){
  const kind=issues.has(issue)?issue:'unreachable';
  return './status.html?issue='+kind+'&from='+encodeURIComponent(safeReturnPage(returnPage));
}
export function classifyConnectionIssue(error,{online=true,status,code,action}={}){
  if(online===false)return 'offline';
  const operation=String(action||error?.action||'');
  // Private judging can fail while the rest of ByteQuest is healthy.
  if(operation==='submission-create'||operation==='native-run')return null;
  const http=Number(status??error?.httpStatus??error?.status??0);
  const reason=String(code??error?.errorCode??error?.code??'').toUpperCase();
  if(http===503&&maintenanceCodes.has(reason))return 'maintenance';
  if(http===429||http===503||http===504)return 'busy';
  const name=String(error?.name||error?.errorName||'');
  if(name==='TimeoutError'||name==='AbortError'||error?.timeout===true)return 'busy';
  if(http===502||http===0)return 'unreachable';
  return null;
}
export function outagePageContent(issue){
  const kind=issues.has(issue)?issue:'unreachable';
  const data={
    offline:{
      eyebrow:'LOCAL CONNECTION',title:'Signal lost.',
      intro:'Your device appears to be offline. ByteQuest cannot confirm cloud saves until your connection returns.',
      detail:'Cached problems and existing drafts may still be available on this device. Keep your browser data intact.',
      diagnostic:'Device is offline',retry:'Check connection',code:'BQ-001'
    },
    busy:{
      eyebrow:'TEMPORARY DELAY',title:'The network is taking a moment.',
      intro:'A ByteQuest request was delayed, rate-limited, or returned a temporary server error.',
      detail:'Your browser drafts have not been cleared. A successful cloud save must be confirmed separately.',
      diagnostic:'Service request delayed',retry:'Try again',code:'BQ-002'
    },
    unreachable:{
      eyebrow:'SERVICE CONNECTION',title:'The route went quiet.',
      intro:'Your device may be online, but ByteQuest could not reach one of the services it needs.',
      detail:'This does not prove a widespread Supabase or Firebase outage. Saved progress may remain available locally.',
      diagnostic:'Service unreachable',retry:'Retry connection',code:'BQ-003'
    },
    maintenance:{
      eyebrow:'PLANNED MAINTENANCE',title:'Fine-tuning the arena.',
      intro:'ByteQuest has reported that a service is in maintenance mode.',
      detail:'Your account changes are not confirmed until the service is available again. Existing browser drafts are not cleared.',
      diagnostic:'Maintenance reported',retry:'Check availability',code:'BQ-004'
    }
  };
  return {kind,...data[kind]};
}
export function issueFromCloudHealth(state,{online=true}={}){
  if(!online)return 'offline';
  if(!state)return null;
  if(state.kind==='maintenance')return 'maintenance';
  if(state.kind==='throttled')return 'busy';
  if(state.kind==='service')return classifyConnectionIssue(
    {httpStatus:state.status??0,errorCode:state.errorCode,action:state.action},
    {online}
  )||'unreachable';
  if(state.kind==='sync-failed'&&(state.status===0||state.status>=500))return classifyConnectionIssue(state,{online})||'unreachable';
  return null;
}

